INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1019, '数学', '三年级', '计算', 2, '{"stem": "先估一估，再用竖式计算：398×6。把 398 看作（ ），6 乘（ ），估算积是（ ）；再精确计算。", "options": null}', '把398看作400，400×6=2400；398×6=2388', '估算：398≈400，6×400=2400；精确：398×6=2388。', 'paper', '["practice", "ykl3sx", "2.9"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1019, '数学', '三年级', '计算', 2, '{"stem": "先估一估，再用竖式计算：503×8。把 503 看作（ ），8 乘（ ），估算积是（ ）；再精确计算。", "options": null}', '把503看作500，500×8=4000；503×8=4024', '估算：503≈500，8×500=4000；精确：503×8=4024。', 'paper', '["practice", "ykl3sx", "2.9"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1019, '数学', '三年级', '应用题', 2, '{"stem": "小海妈妈想买3束98元/束的花，300元够吗？（先估一估）", "options": null}', '够。把98看作100，100×3=300；98<100，所以 300 元够。', '估算：98≈100，3×100=300（元），实际 3×98=294（元）<300 → 够。', 'paper', '["practice", "ykl3sx", "2.9"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1019, '数学', '三年级', '应用题', 3, '{"stem": "服装公司要完成一笔180件衬衫的订单。如果一匹布可以做22件衬衫，准备9匹布够吗？", "options": null}', '够。把22看作20，20×9=180；因为22>20，实际可做 22×9=198>180 件 → 够。', '估算：22≈20，9 匹约可做 180 件；实际 22×9=198 件 >180 件 → 够。', 'paper', '["practice", "ykl3sx", "2.9"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1019, '数学', '三年级', '应用题', 3, '{"stem": "亮亮爸爸想买4把椅子，每把208元。他估算「把208看作200，200×4=800，带800元就可以了」。亮亮的估算方法是（填“合理”或“不合理”）的。如果不合理，你的估算方法是（列式解答）。", "options": null}', '不合理。把 208 看作 210，210×4=840（元），因为 208<210，所以带 840 元就够了。', '208≈200 会少估：实际 4×208=832>800，带 800 元不够 → 不合理。应往大估：208≈210，210×4=840（元）>832，够。', 'paper', '["practice", "ykl3sx", "2.9"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
