INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1019, '数学', '三年级', '填空', 3, '{"stem": "通过估算得知，□4×8 的积在 320 和 400 之间，□ 里可以填（ ）。", "options": null}', '4', '44×8=352 在 320~400 之间 ✓；34×8=272<320 ✗；54×8=432>400 ✗ → □=4。', 'paper', '["practice", "ykl3sx", "2.9"]', NULL, 0);

